from mutate_security import SECURITY_M, SECURITY_EQUIVALENT  # security lane
M += SECURITY_M
EQUIVALENT = {"learn-offtask-not-gated": "unreachable: every off-task steer is trace-only in the guard (upstream: until the score is calibrated), so the gate behind `!OffTaskTraceOnly` is never asked",
 "learn-recommend-top-five": "unreachable: at most two threshold adjustments and three exempt insights, so five recommendations is the most there can be",
 "learn-pending-outcome-stored": "unreachable: noteOutcomes is only handed records whose outcome just landed; the guard is upstream's defence in depth",
 "learning-thresholds-floor": "the outer floor of ten holds is redundant: the only suggestion it gates needs twenty holds of its own",
 "learning-steer-top-limit": "unreachable: steer types are five (irreversible, off-task, intent-mismatch, pattern, other), so the top-five limit never cuts",
 "stuck-diff-on-success": "unreachable: a successful latest result reaches a stuck verdict only as a success repeat or churn, which the same condition already excludes",
 "subagent-collects-any-custom-type": "newReports filters the notify types again before triage; the collection filter only keeps the pending list small",
 "judge-when-disabled": "unreachable: toolcall.go returns before judgeFor when warden is off; the check stays as defence in depth",
 "sensitive-violations-escalate": "unreachable: only rm-family hits yield violations (hitViolations), and none is sensitive; the filter is upstream's defence in depth",
 "large-output-any-tool": "unreachable: BuildRequest asks the large_output question of bash only, so no other tool has an answer to read",
 "scratch-moves-in-ignored": "the stripped command is read too (`unquoted(command)`); the raw text only adds a case where data text hid a move-in word",
 "sql-commit-voids-nothing": "redundant by construction: a COMMIT is also a transaction-control statement (SQL_TX_CONTROL) and a trailing one is not the final ROLLBACK, so the void list is a second line of defence",
 "large-output-memory-lost": "the steer repeat window drops the identical second text, so the memory is a second line of defence (checked at the unit level by the notice twin)"}
EQUIVALENT["banner-only-on-first-block"] = "a notice and several text blocks never meet outside the per-block path: more than one block means judged per block, and a block that is not judged (a duplicate or a recall) has no verdict, so no notice"
EQUIVALENT.update(SECURITY_EQUIVALENT)
EQUIVALENT["state-reminder-while-awaiting-user"] = "redundant in the original too: assess selects nothing unless the disposition is advance, so a fresh assessment that awaits the user has no selection and the earlier test of the selection already stops the reminder"
EQUIVALENT["state-loaded-bytes-not-counted"] = "the counter is read only by the next load of the same prompt, and the original loads at most once a prompt (before_agent_start); it starts again at 0 for every prompt"
only = set(sys.argv[1:])
out = []
for mid, f, old, new in M:
    if only and mid not in only: continue
    p = os.path.join(ext, f); src = open(p).read()
    if src.count(old) != 1:
        out.append(f"{mid}: SKIPPED (pattern matches {src.count(old)}x in {f})"); print(out[-1]); continue
    shutil.copy(p, p + ".orig")
    try:
        open(p, "w").write(src.replace(old, new))
        try:
            r = subprocess.run(["go", "test", "-count=1", "-failfast", "-timeout=120s"] + (["-run", os.environ["MUTATE_RUN"]] if os.environ.get("MUTATE_RUN") else []) + ["."], cwd=ext, capture_output=True, text=True, timeout=300)
        except subprocess.TimeoutExpired:
            out.append(f"{mid}: KILLED (the mutant hangs: the test binary timed out)"); print(out[-1], flush=True); continue
        killed = r.returncode != 0
        first = next((l for l in (r.stdout + r.stderr).splitlines() if l.startswith("--- FAIL") or "build failed" in l or "[setup failed]" in l or "panic: test timed out" in l), "")
        out.append(f"{mid}: {'KILLED' if killed else 'SURVIVED (equivalent mutant: ' + EQUIVALENT[mid] + ')' if mid in EQUIVALENT else 'SURVIVED'} {first}".rstrip())
    finally:
        shutil.move(p + ".orig", p)
    print(out[-1], flush=True)
results = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mutation-results.txt")
if only and os.path.exists(results):
    # A subset run replaces its own lines and keeps the rest.
    old = {l.split(":", 1)[0]: l for l in open(results).read().splitlines() if l}
    for l in out:
        old[l.split(":", 1)[0]] = l
    out = list(old.values())
open(results, "w").write("\n".join(out) + "\n")
